'use strict';

const fs = require('fs');
const os = require('os');
const path = require('path');
const Database = require('better-sqlite3');
const config = require('../src/config');
const db = require('../src/db');
const settings = require('../src/services/settings');

/**
 * Importe l'ancienne base SQLite dans PostgreSQL, en conservant les identifiants
 * (les clés sont « GENERATED BY DEFAULT », donc un id explicite est accepté).
 * Les tables sont remplies dans l'ordre des dépendances, puis les compteurs sont
 * repositionnés au-dessus des ids importés.
 *
 * La source n'est jamais modifiée : après vérification des lignes, le fichier
 * SQLite est renommé en *.sqlite.archived pour qu'un second import parte d'une
 * base vide.
 *
 * Usage : node scripts/migrate-to-postgres.js [--from data/rent.sqlite] [--force]
 */

const TABLES = [
  { name: 'floors', columns: ['id', 'label', 'short_label', 'position', 'created_at'] },
  { name: 'unit_types', columns: ['code', 'label', 'default_rent', 'position'] },
  { name: 'tenants', columns: ['id', 'first_name', 'last_name', 'phone', 'address', 'notes',
    'status', 'departure_date', 'created_at', 'email'] },
  { name: 'units', columns: ['id', 'floor_id', 'unit_type_code', 'name', 'default_rent', 'status',
    'notes', 'created_at'] },
  { name: 'tenancies', columns: ['id', 'tenant_id', 'unit_id', 'start_date', 'end_date', 'monthly_rent',
    'unit_name', 'floor_label', 'unit_type_label', 'notes'] },
  { name: 'payments', columns: ['id', 'tenancy_id', 'period_year', 'period_month', 'expected_amount',
    'amount', 'paid_at', 'method', 'note', 'created_at'] },
  { name: 'receipts', columns: ['id', 'number', 'type', 'tenancy_id', 'period_year', 'period_month',
    'amount_this', 'total_paid', 'expected', 'balance', 'payment_date', 'method', 'observations',
    'issued_at', 'issued_place', 'snapshot', 'cancelled'] },
  { name: 'receipt_sequences', columns: ['year', 'last_value'] },
  { name: 'settings', columns: ['key', 'value'] },
  { name: 'receipt_transmissions', columns: ['id', 'receipt_id', 'channel', 'status', 'recipient',
    'detail', 'created_at'] },
];

function parseArgs() {
  const args = process.argv.slice(2);
  return {
    from: args.includes('--from') ? args[args.indexOf('--from') + 1] : config.sqlitePath,
    force: args.includes('--force'),
  };
}

/** Valeur SQLite convertie vers son équivalent PostgreSQL. */
function convert(column, value) {
  if (value === undefined) return null;
  if (column === 'cancelled') return !!value;
  if (column === 'snapshot') {
    if (value === null || value === '') return '{}';
    JSON.parse(value); // échoue bruyamment plutôt que d'importer un instantané illisible
    return value;
  }
  return value;
}

/** Colonnes réellement présentes dans la source : un archive plus ancien que la
 * dernière migration ne possède pas toutes les colonnes, et l'import ne doit pas
 * échouer pour si peu. */
function sourceColumns(source, table) {
  if (!source.prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name = ?")
    .get(table.name)) return null;
  const present = new Set(source.prepare(`PRAGMA table_info(${table.name})`).all().map(c => c.name));
  return table.columns.filter(c => present.has(c));
}

async function importTable(source, table) {
  const columns = sourceColumns(source, table);
  if (!columns) {
    console.warn(`  ${table.name} : absente de l'archive SQLite, ignorée.`);
    return 0;
  }
  const rows = source.prepare(`SELECT ${columns.join(', ')} FROM ${table.name}`).all();
  if (!rows.length) return 0;
  const placeholders = columns.map((c, i) => `$${i + 1}`).join(', ');
  const sql = `INSERT INTO ${table.name} (${columns.join(', ')}) VALUES (${placeholders})`;
  let inserted = 0;
  await db.tx(async () => {
    for (const row of rows) {
      await db.query(sql, columns.map(c => convert(c, row[c])));
      inserted++;
    }
  });
  return inserted;
}

/** Repositionne chaque compteur sur max(id) pour que les prochains insertions
 * ne percutent pas les identifiants importés. */
async function resetSequences() {
  const tables = ['floors', 'tenants', 'units', 'tenancies', 'payments', 'receipts', 'receipt_transmissions'];
  for (const t of tables) {
    const { rows } = await db.pool.query(
      `SELECT setval(pg_get_serial_sequence('${t}', 'id'),
                      GREATEST((SELECT COALESCE(MAX(id), 1) FROM ${t}), 1), true)`);
    console.log(`  compteur ${t}.id → ${rows[0].setval}`);
  }
}

function countInSqlite(source, name) {
  if (!source.prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name = ?").get(name)) return 0;
  return source.prepare(`SELECT COUNT(*) AS c FROM ${name}`).get().c;
}

async function main() {
  const { from, force } = parseArgs();
  if (!fs.existsSync(from)) {
    console.error(`Base SQLite introuvable : ${from}`);
    process.exitCode = 1;
    return;
  }

  console.log(`Source  : ${from}`);
  console.log(`Cible   : ${config.databaseLabel}`);

  // L'archive peut avoir tout son contenu dans son fichier -wal non reporté :
  // on part d'une copie cohérente plutôt que de lire le seul fichier principal.
  const snapshot = path.join(os.tmpdir(), `rent-import-${Date.now()}.sqlite`);
  const raw = new Database(from, { readonly: true });
  await raw.backup(snapshot);
  raw.close();
  const source = new Database(snapshot, { readonly: true });
  console.log(`Copie lue : ${snapshot}`);

  try {
    await db.assertReachable();
    await db.migrate();

    const existing = await db.query('SELECT COUNT(*) AS c FROM tenants');
    if (Number(existing.rows[0].c) > 0 && !force) {
      console.error(`La base de destination contient déjà ${existing.rows[0].c} locataire(s) : `
        + 'l\'import remplace tout son contenu. Relancez avec --force pour confirmer.');
      process.exitCode = 1;
      return;
    }

    const report = [];
    // Tout ou rien, sur une destination vidée : les valeurs par défaut créées au
    // premier démarrage (étages, types, paramètres) laissent place à l'archive,
    // qui reste la source de vérité.
    await db.tx(async () => {
      await db.query(`TRUNCATE floors, unit_types, tenants, units, tenancies, payments, receipts,
                      receipt_sequences, settings, receipt_transmissions RESTART IDENTITY CASCADE`);
      for (const table of TABLES) {
        const before = countInSqlite(source, table.name);
        const after = await importTable(source, table);
        // db.query (et non db.pool) : la requête doit rester dans la transaction
        // d'import, sinon elle attend indéfiniment les verrous du TRUNCATE.
        const inPg = Number((await db.query(`SELECT COUNT(*) AS c FROM ${table.name}`)).rows[0].c);
        report.push({ table: table.name, sqlite: before, imported: after, postgresql: inPg });
      }
    });

    await resetSequences();
    await settings.reload();

    console.log('\nTable                   SQLite  Importé  PostgreSQL');
    let ok = true;
    for (const r of report) {
      if (r.postgresql !== r.sqlite) ok = false;
      console.log(`${r.table.padEnd(24)} ${String(r.sqlite).padStart(5)}  ${String(r.imported).padStart(6)}`
        + `  ${String(r.postgresql).padStart(9)}`);
    }
    if (!ok) {
      console.error('\nÉcart entre les deux bases : l\'archive n\'est pas renommée, vérifiez avant de réimporter.');
      process.exitCode = 1;
      return;
    }

    archive(from);
  } finally {
    source.close();
    fs.rmSync(snapshot, { force: true });
    await db.close();
  }
}

/** Renomme le trio .sqlite / -wal / -shm ensemble : séparés, ils ne forment
 * plus une base consultable. Aucun fichier n'est supprimé. */
function archive(from) {
  const archived = `${from}.archived`;
  if (fs.existsSync(archived)) {
    console.log(`\nArchive déjà présent : ${archived}`);
    return;
  }
  for (const suffix of ['', '-wal', '-shm']) {
    if (fs.existsSync(from + suffix)) fs.renameSync(from + suffix, archived + suffix);
  }
  console.log(`\nImport terminé et vérifié. L'ancienne base est archivée sous ${archived}.`);
}

main().catch(async (err) => {
  console.error(`Import interrompu : ${err.message}`);
  await db.close().catch(() => {});
  process.exitCode = 1;
});
